# CBT terrain's compute kernels. Two things make these unlike every other entry above.
#
# GE_CBT_HEAP32 selects the narrow-heap arm of cbt_layout.glsl: the shipped kernels put the
# bisector heap ID in a uint64_t and walk the barycentric decode in i64vec3, and WGSL has no
# 64-bit integer at all. The narrow arm is the same algorithm at u32 width, which costs
# subdivision RANGE (kHeap32DecodeSubdiv, mirrored by the host clamp) and nothing else.
#
# KERNEL=i picks one kernel out of the file's switch. The desktop build compiles ONE blob
# and specializes constant_id=0 kCBTKernelCount ways; WebGPU has no specialization
# constants, so each kernel is its own cooked program instead. The names mirror
# CBTKernelSet::KernelProgramFileName, which is what the loader opens.
#
# The count is READ from CBTKernelSet.h rather than repeated here. A hand-copied count that
# falls behind the enum cooks a short set, and the failure surfaces at terrain bring-up as
# one pipeline that will not load — far from the edit that caused it. Parsing turns that
# into a cook-time error naming the file.
def CBTKernelCount() -> int:
    header = kRepoRoot / "Engine" / "Modules" / "CBTTerrain" / "Include" / "CBTTerrain" / \
        "CBTKernelSet.h"
    match = re.search(r"Count\s*=\s*(\d+)\s*[,}]", header.read_text())
    if match is None:
        raise RuntimeError(f"cannot read CBTKernel::Count from {header}")
    return int(match.group(1))


kEditorStageShaders.update({
    f"CBT/cbt_kernels_{i}.comp": ("CBT/cbt_kernels.comp", ["GE_CBT_HEAP32", f"KERNEL={i}u"])
    for i in range(CBTKernelCount())
})

kStageNames = {"vs": "vertex", "fs": "fragment", "cs": "compute"}
kStageByExtension = {".vert": "vertex", ".frag": "fragment", ".comp": "compute"}

# The built-in packages compile under the same profile as the cooked material
# variants (MaterialVariantCook --web): explicit-LOD taps, flat derivatives and
# the WebGPU-legal shadow bindings. Without it these sources reach tint with
# non-uniform derivative and comparison-sampling calls it rejects.
kWebDefines = ["GE_COMPAT_PROFILE"]

class CookFailure(Exception):
    """One package failed; the caller decides whether that is fatal."""


# The .shaderpkg container is read and written only by the engine's
# ShaderReflect tool (ShaderPackageContainer), never here: one reader and one
# writer of the format. These wrap the tool's package modes.
def RunShaderReflect(reflector: Path, args: list[str | Path]) -> str:
    result = shadercook.Run([reflector, *args])
    if result.returncode != 0:
        raise CookFailure(f"ShaderReflect {' '.join(str(a) for a in args)} failed: "
                          f"{(result.stderr or result.stdout).strip()}")
    return result.stdout


def ListShaderPkgChunks(reflector: Path, path: Path) -> list[dict]:
    """The package's chunk table: [{"name", "type", "size"}, ...] in file order."""
    return json.loads(RunShaderReflect(reflector, ["--list-chunks", path]))


def ReadShaderPkgChunk(reflector: Path, path: Path, name: str) -> bytes:
    with tempfile.TemporaryDirectory() as tempDir:
        out = Path(tempDir) / "chunk.bin"
        RunShaderReflect(reflector, ["--read-chunk", path, "--chunk", f"{name}={out}"])
        return out.read_bytes()


def ReadShaderPkgMeta(reflector: Path, path: Path) -> dict:
    """The package's reflection metadata, as the tool prints it."""
    return json.loads(RunShaderReflect(reflector, ["--inspect", path]))


def AppendShaderPkgChunks(reflector: Path, path: Path, chunks: list[tuple[str, Path]]) -> None:
    args: list[str | Path] = ["--append-chunk", path]
    for name, source in chunks:
        args += ["--chunk", f"{name}={source}"]
    RunShaderReflect(reflector, args)


def StripShaderPkgSpirv(reflector: Path, paths: list[Path], batch: int = 64) -> None:
    """Rewrite each package without the SPIR-V of every stage that also carries WGSL."""
    for start in range(0, len(paths), batch):
        RunShaderReflect(reflector, ["--strip-spirv-with-wgsl", *paths[start:start + batch]])


def FindToolchain() -> tuple[Path, Path, Path | None]:
    glslc = shadercook.FindTool("glslc", None)
    naga = shadercook.FindTool("naga", None)
    tint = shadercook.FindTool("tint", None)
    if glslc is None:
        raise RuntimeError("glslc not found — install the Vulkan SDK")
    if naga is None:
        raise RuntimeError("naga not found — run Tools/ShaderCook/toolchain/setup.py to fetch it")
    return glslc, naga, tint


def FindShaderReflect(shaderPkgDir: Path, explicit: Path | None = None) -> Path:
    """Find the host packager beside the desktop shader build or staged editor."""
    configured = explicit or os.environ.get("GE_SHADERREFLECT_EXECUTABLE")
    if configured:
        path = Path(configured)
        if not path.is_file():
            raise RuntimeError(f"ShaderReflect does not exist: {path}")
        return path
    name = "ShaderReflect.exe" if sys.platform == "win32" else "ShaderReflect"
    for parent in (shaderPkgDir, *shaderPkgDir.parents):
        candidates = [parent / "Tools" / name, parent / "bin" / "Tools" / name]
        candidates += sorted((parent / "bin").glob(f"*/Tools/{name}"))
        found = [path for path in candidates if path.is_file()]
        if found:
            return max(found, key=lambda path: path.stat().st_mtime_ns)
    found = shadercook.FindTool("ShaderReflect", None)
    if found is not None:
        return found
    raise RuntimeError("ShaderReflect not found — build the desktop ShaderReflect target "
                       "or pass --shader-reflect / set GE_SHADERREFLECT_EXECUTABLE")


# Not every built-in package's source sits in Rendering/Shaders. Modules own
# their own (HeightFog), and engine packages own theirs under Assets/Shaders
# (film-simulation, chromatic-aberration), so a package name alone does not say
# where its stages live. The search is ordered: the engine shader dir first, so
# nothing here can shadow a core shader, then the module and package roots.
kExtraShaderRoots = [
    kRepoRoot / "Engine" / "Modules",
    kRepoRoot / "Packages",
]

# Include roots for includes that cross a module boundary. The runtime passes the same set
# (TerrainGrassRenderFeature::EnsureComputePipeline hands the placement shader CBT's dir for
# the bare-name cbt_atlas.glsl, plus the grass module's Shaders root so its own
# "TerrainGrass/…" includes resolve), so the cook resolves what the engine resolves.
kSharedShaderRoots = [
    kRepoRoot / "Engine" / "Modules" / "CBTTerrain" / "Shaders" / "CBT",
    kRepoRoot / "Engine" / "Modules" / "TerrainGrass" / "Shaders",
]


def ResolveShaderSource(sourceName: str, shaderSourceDir: Path) -> Path:
    direct = shaderSourceDir / sourceName
    if direct.is_file():
        return direct
    # A subdirectory of the engine shader dir, which is where the ocean keeps
    # its stages (Shaders/Ocean). Searched after the root so a subdirectory
    # cannot shadow a core shader of the same name, and before the module roots
    # for the same reason.
    nested = sorted(shaderSourceDir.glob(f"*/{sourceName}"))
    if nested:
        return nested[0]
    for root in kExtraShaderRoots:
        found = sorted(root.glob(f"*/Shaders/{sourceName}")) + \
                sorted(root.glob(f"*/Assets/Shaders/{sourceName}"))
        if found:
            return found[0]
    # Report the path the caller asked for: the error then names the shader the
    # package declared rather than the last directory that happened to be tried.
    return direct


def CookBuiltinPackages(shaderPkgDir: Path, shaderSourceDir: Path, outDir: Path,
                        validate: bool = True,
                        packages: dict[str, dict[str, str]] | None = None,
                        shaderReflect: Path | None = None
                        ) -> list[tuple[str, str]]:
    """Write WGSL-carrying copies of every built-in package into `outDir`.

    Returns the list of (package, error) failures; an empty list means the
    whole set cooked. Raises RuntimeError only when the toolchain is missing,
    which is an environment fault rather than a content one.
    """
    glslc, naga, tint = FindToolchain()
    reflector = FindShaderReflect(shaderPkgDir, shaderReflect)

    failures: list[tuple[str, str]] = []
    for packageName, stages in (packages if packages is not None else kPackages).items():
        sourcePkg = shaderPkgDir / f"{packageName}.shaderpkg"
        if not sourcePkg.exists():
            failures.append((packageName, f"missing desktop package {sourcePkg}"))
            continue
        try:
            with tempfile.TemporaryDirectory() as tempDir:
                scratch = Path(tempDir)
                wgslChunks = []
                reflectionArgs = [reflector]
                for stageKey, sourceName in stages.items():
                    outWgsl = scratch / f"{packageName}.{stageKey}.wgsl"
                    source = ResolveShaderSource(sourceName, shaderSourceDir)
                    shadercook.CookFile(source, kStageNames[stageKey],
                                        glslc, naga, tint, validate, kWebDefines,
                                        [shaderSourceDir, source.parent], outWgsl, scratch)
                    wgslChunks.append((f"{stageKey}-wgsl", outWgsl))
                    # Reflect the preprocessed GLSL before the cook lowers push
                    # constants into the backend's emulation buffer. Runtime
                    # metadata keeps the engine abstraction for those constants.
                    flattened = scratch / (source.stem + ".pp" + source.suffix)
                    reflectedSpv = scratch / f"{packageName}.{stageKey}.reflect.spv"
                    result = shadercook.Run([glslc, "--target-env=vulkan1.1",
                        f"-fshader-stage={kStageNames[stageKey]}", flattened, "-o", reflectedSpv])
                    if result.returncode != 0:
                        raise CookFailure(f"reflection compile failed for {source}: {result.stderr}")
                    reflectionArgs += [f"--{stageKey}", reflectedSpv]
                reflectedPkg = scratch / f"{packageName}.shaderpkg"
                result = shadercook.Run(reflectionArgs + ["--out", reflectedPkg])
                if result.returncode != 0:
                    raise CookFailure(f"ShaderReflect failed for {packageName}: {result.stderr or result.stdout}")
                AppendShaderPkgChunks(reflector, reflectedPkg, wgslChunks)
                outDir.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(reflectedPkg, outDir / f"{packageName}.shaderpkg")
        except (shadercook.CookError, CookFailure) as error:
            failures.append((packageName, str(error)))
    return failures


def CookStageShaders(shaderSourceDir: Path, outDir: Path, validate: bool = True,
                     stages: dict[str, tuple[str, list[str]]] | None = None
                     ) -> list[tuple[str, str]]:
    """Cook the package-less stage shaders into `<name>.wgsl` under `outDir`."""
    glslc, naga, tint = FindToolchain()
    outDir.mkdir(parents=True, exist_ok=True)

    failures: list[tuple[str, str]] = []
    for name, (sourceName, extraDefines) in (
            stages if stages is not None else kEditorStageShaders).items():
        # Same resolution the packages use: a module that owns its own shaders (CBT) is
        # not under the engine shader root, and a name alone does not say where it lives.
        source = ResolveShaderSource(sourceName, shaderSourceDir)
        stage = kStageByExtension.get(source.suffix)
        if stage is None:
            failures.append((name, f"cannot infer a stage from '{source.name}'"))
            continue
        try:
            # Cooked in scratch so the sampler-remap sidecar CookFile drops
            # beside its output stays out of the shipped tree.
            with tempfile.TemporaryDirectory() as tempDir:
                scratch = Path(tempDir)
                cooked = scratch / f"{Path(name).name}.wgsl"
                # source.parent so a module's shader resolves its siblings by bare name;
                # kSharedShaderRoots for the cross-module bare-name includes the runtime
                # passes explicitly (grass placement includes CBT's cbt_atlas.glsl so the
                # blades resolve the atlas exactly as the surface does).
                shadercook.CookFile(source, stage, glslc, naga, tint, validate,
                                    kWebDefines + extraDefines,
                                    [shaderSourceDir, source.parent] + kSharedShaderRoots,
                                    cooked, scratch)
                # A name may carry a subdirectory (CBT/…), mirroring the staged layout the
                # runtime probes.
                target = outDir / f"{name}.wgsl"
                target.parent.mkdir(parents=True, exist_ok=True)
                target.write_bytes(cooked.read_bytes())
        except shadercook.CookError as error:
            failures.append((name, str(error)))
    return failures


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0],
                                     formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--shaderpkg-dir", type=Path, required=True,
                        help="desktop build's Shaders/ dir (SPIR-V .shaderpkg + reflection)")
    parser.add_argument("--shader-reflect", type=Path,
                        help="host ShaderReflect executable (default: desktop build or PATH)")
    parser.add_argument("--out", type=Path, required=True,
                        help="directory to write the cooked packages and stage shaders into")
    parser.add_argument("--engine-shaders", type=Path,
                        default=kRepoRoot / "Engine" / "Modules" / "Rendering" / "Shaders",
                        help="engine GLSL shader source root")
    parser.add_argument("--editor", action="store_true",
                        help="also cook the Editor-only packages and stage shaders")
    args = parser.parse_args()

    packages = dict(kPackages)
    if args.editor:
        packages.update(kEditorPackages)

    try:
        failures = CookBuiltinPackages(args.shaderpkg_dir, args.engine_shaders,
                                       args.out, packages=packages,
                                       shaderReflect=args.shader_reflect)
        if args.editor:
            failures += CookStageShaders(args.engine_shaders, args.out)
    except RuntimeError as error:
        print(f"builtin_shader_cook: {error}", file=sys.stderr)
        return 2

    for name, error in failures:
        print(f"  FAILED {name}: {error.splitlines()[0] if error else ''}", file=sys.stderr)
    if failures:
        print(f"builtin_shader_cook: {len(failures)} shader(s) failed to cook", file=sys.stderr)
        return 1

    cooked = len(packages) + (len(kEditorStageShaders) if args.editor else 0)
    print(f"builtin_shader_cook: {cooked} artifacts -> {args.out}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
